if ("geolocation" in navigator) {
    var userMarker = null, userCircle = null, currentLatLng = null;

    var locateControl = L.control({position: 'topleft'});
    locateControl.onAdd = function(map) {
        var div = L.DomUtil.create('div', 'leaflet-bar leaflet-control');
        div.innerHTML = '<button title="Ke Lokasi Saya" style="background-color: #fff; border: 2px solid rgba(0,0,0,0.2); width: 34px; height: 34px; line-height: 30px; text-align: center; cursor: pointer; border-radius: 4px; font-size: 16px; display: flex; align-items: center; justify-content: center;"><i class="fa fa-crosshairs" style="color: #007bff; font-size: 18px;"></i></button>';
        div.onclick = function(e) {
            e.stopPropagation();
            if (currentLatLng) {
                map_8c606eefbbae33fb798fc87f14c40000.flyTo(currentLatLng, 17, {animate: true, duration: 1.5});
            } else {
                alert("Sedang mendeteksi lokasi GPS Anda...");
            }
        };
        return div;
    };
    locateControl.addTo(map_8c606eefbbae33fb798fc87f14c40000);

    navigator.geolocation.watchPosition(function(pos) {
        var lat = pos.coords.latitude, lng = pos.coords.longitude, acc = pos.coords.accuracy;
        currentLatLng = [lat, lng];
        if (!userMarker) {
            userMarker = L.marker(currentLatLng).addTo(map_8c606eefbbae33fb798fc87f14c40000).bindPopup("Lokasi Anda");
            userCircle = L.circle(currentLatLng, {radius: Math.min(acc, 500), color: '#007bff', fillColor: '#007bff', fillOpacity: 0.15, weight: 1}).addTo(map_8c606eefbbae33fb798fc87f14c40000);
            map_8c606eefbbae33fb798fc87f14c40000.setView(currentLatLng, 16);
        } else {
            userMarker.setLatLng(currentLatLng);
            userCircle.setLatLng(currentLatLng);
            userCircle.setRadius(Math.min(acc, 500));
        }
    }, function(err){ console.warn(err.message); }, {enableHighAccuracy: true});
}


